ALTER TABLE "app"."referral_registration" DROP CONSTRAINT "referral_registration_reward";--> statement-breakpoint
ALTER TABLE "app"."referral_registration" ADD COLUMN "invitee_points" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "app"."referral_registration" ADD CONSTRAINT "referral_registration_inviter_reward" CHECK (("app"."referral_registration"."status" = 'rewarded' and "app"."referral_registration"."points" > 0 and "app"."referral_registration"."rewarded_at" is not null and "app"."referral_registration"."qualified_at" is not null) or ("app"."referral_registration"."status" <> 'rewarded' and "app"."referral_registration"."points" = 0 and "app"."referral_registration"."rewarded_at" is null));--> statement-breakpoint
ALTER TABLE "app"."referral_registration" ADD CONSTRAINT "referral_registration_invitee_reward" CHECK ("app"."referral_registration"."invitee_points" = 0 or ("app"."referral_registration"."invitee_points" > 0 and "app"."referral_registration"."status" in ('rewarded','capped') and "app"."referral_registration"."qualified_at" is not null));